def parse_header(line):
    return [h for h in line.split(",")]


def parse_rows(text):
    lines = text.split("\n")
    header = parse_header(lines[0])
    rows = []
    for line in lines[1:]:
        cells = line.split(",")
        rows.append(dict(zip(header, cells)))
    return rows

