import unittest
from importer import parse_rows


class Regression(unittest.TestCase):
    def test_plain_rows(self):
        rows = parse_rows("a,b\n1,2\n3,4")
        self.assertEqual(rows, [{"a": "1", "b": "2"}, {"a": "3", "b": "4"}])

    def test_whitespace_only_lines_are_skipped_too(self):
        self.assertEqual(parse_rows("a\nx\n   \ny"), [{"a": "x"}, {"a": "y"}])

    def test_empty_cells_are_kept(self):
        self.assertEqual(parse_rows("a,b\n1,"), [{"a": "1", "b": ""}])

