import csv


def parse_header(line):
    return [h.strip().lower() for h in next(csv.reader([line]))]


def parse_rows(text):
    lines = text.split("\n")
    header = parse_header(lines[0])
    rows = []
    for line in lines[1:]:
        if not line.strip():
            continue
        cells = next(csv.reader([line]))
        rows.append(dict(zip(header, cells)))
    return rows

